const { useState } = React;

function validate(form) {
  const found = {};
  if (form.title.trim() === '') found.title = '제목을 입력해 주세요';
  if (Number(form.hours) < 1) found.hours = '시간은 1 이상이어야 합니다';
  return found;
}

function CourseForm() {
  const [form, setForm] = useState({ title: '', hours: '0' });
  const [errors, setErrors] = useState({});
  const [sent, setSent] = useState(null);

  const change = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const submit = (e) => {
    e.preventDefault();
    const found = validate(form);
    setErrors(found);

    if (Object.keys(found).length > 0) {
      setSent(null);
      return;
    }

    setSent(form.title + ' · ' + form.hours + '시간');
  };

  return (
    <form onSubmit={submit}>
      <label className="field" htmlFor="title">제목</label>
      <input
        className="field__input"
        id="title"
        name="title"
        value={form.title}
        onChange={change}
        aria-invalid={errors.title ? true : undefined}
        aria-describedby={errors.title ? 'title-error' : undefined}
      />
      {errors.title && <p className="err" id="title-error">{errors.title}</p>}

      <label className="field" htmlFor="hours">시간</label>
      <input
        className="field__input"
        id="hours"
        name="hours"
        type="number"
        value={form.hours}
        onChange={change}
        aria-invalid={errors.hours ? true : undefined}
        aria-describedby={errors.hours ? 'hours-error' : undefined}
      />
      {errors.hours && <p className="err" id="hours-error">{errors.hours}</p>}

      <button className="go" type="submit">등록</button>

      <p className="result">{sent === null ? '아직 보내지 않았습니다' : '보냄: ' + sent}</p>
    </form>
  );
}

ReactDOM.createRoot(document.querySelector('#root')).render(<CourseForm />);

